\subsubsection{ENH-01: Deterministic per-buffer Python LSP
dispatcher}\label{enh-01-deterministic-per-buffer-python-lsp-dispatcher}

\begin{itemize}
\tightlist
\item
  Location: org heading "Lang: Python/lsp"
\item
  Status: enhancement (priority P1)
\item
  Evidence: DUP-03 to DUP-05
\item
  Recommendation: replaces the two Python lambdas in the
  \texttt{lsp-mode} \texttt{:hook} (heading "Lang: LSP.mode"), the
  \texttt{:hook} of \texttt{use-package\ python}, the
  \texttt{defvar-local\ h7/python-use-eglot},
  \texttt{h7/python-lsp-switch} and the notebook \texttt{add-hook}
  block. Directory-local variables are read through
  \texttt{hack-local-variables-hook}\footnote{Emacs Lisp manual, File
    Local Variables,
    \url{https://www.gnu.org/software/emacs/manual/html_node/elisp/File-Local-Variables.html}},
  which runs after the mode hooks.
\item
  Risk: Medium; Effort: Medium; Confidence: Medium
\item
  Rollback: restore the removed blocks from git
\end{itemize}

\begin{Shaded}
\begin{Highlighting}[]
\NormalTok{(defcustom h7/python{-}lsp{-}backend \textquotesingle{}auto}
\NormalTok{  "LSP client for Python buffers: \textasciigrave{}lsp\textquotesingle{}, \textasciigrave{}eglot\textquotesingle{} or \textasciigrave{}auto\textquotesingle{}."}
\NormalTok{  :type \textquotesingle{}(choice (const auto) (const lsp) (const eglot))}
\NormalTok{  :safe \#\textquotesingle{}symbolp}
\NormalTok{  :group \textquotesingle{}python)}

\NormalTok{(defun h7/python{-}notebook{-}p ()}
\NormalTok{  "Non{-}nil if this buffer is a percent{-}format notebook script."}
\NormalTok{  (and buffer{-}file{-}name}
\NormalTok{       (or (member "notebooks"}
\NormalTok{                   (split{-}string}
\NormalTok{                    (file{-}name{-}directory buffer{-}file{-}name) "/" t))}
\NormalTok{           (save{-}excursion}
\NormalTok{             (save{-}restriction}
\NormalTok{               (widen)}
\NormalTok{               (goto{-}char (point{-}min))}
\NormalTok{               (re{-}search{-}forward "\^{}\# \%\%" (min (point{-}max) 65536) t))))))}

\NormalTok{(defun h7/python{-}lsp{-}choice ()}
\NormalTok{  "Return \textasciigrave{}lsp\textquotesingle{} or \textasciigrave{}eglot\textquotesingle{} for the current buffer."}
\NormalTok{  (pcase h7/python{-}lsp{-}backend}
\NormalTok{    ((or \textquotesingle{}lsp \textquotesingle{}eglot) h7/python{-}lsp{-}backend)}
\NormalTok{    (\_ (if (h7/python{-}notebook{-}p) \textquotesingle{}eglot \textquotesingle{}lsp))))}

\NormalTok{(defun h7/python{-}lsp{-}start ()}
\NormalTok{  "Start exactly one LSP client in the current Python buffer."}
\NormalTok{  (when (and buffer{-}file{-}name}
\NormalTok{             (derived{-}mode{-}p \textquotesingle{}python{-}base{-}mode)}
\NormalTok{             (not (bound{-}and{-}true{-}p lsp{-}mode))}
\NormalTok{             (not (and (fboundp \textquotesingle{}eglot{-}managed{-}p) (eglot{-}managed{-}p))))}
\NormalTok{    (if (eq (h7/python{-}lsp{-}choice) \textquotesingle{}eglot)}
\NormalTok{        (eglot{-}ensure)}
\NormalTok{      (lsp{-}deferred))))}

\NormalTok{(add{-}hook \textquotesingle{}hack{-}local{-}variables{-}hook \#\textquotesingle{}h7/python{-}lsp{-}start)}

\NormalTok{(defun h7/python{-}lsp{-}status ()}
\NormalTok{  "Report which LSP clients manage the current buffer."}
\NormalTok{  (interactive)}
\NormalTok{  (let ((lsp (bound{-}and{-}true{-}p lsp{-}mode))}
\NormalTok{        (eg (and (fboundp \textquotesingle{}eglot{-}managed{-}p) (eglot{-}managed{-}p))))}
\NormalTok{    (message "lsp{-}mode: \%s, eglot: \%s\%s" lsp eg}
\NormalTok{             (if (and lsp eg) "  \textless{}{-}{-} CONFLICT" ""))))}
\end{Highlighting}
\end{Shaded}

A notebook directory can also be forced with a file named
\texttt{.dir-locals.el} in the \texttt{notebooks} folder:

