\section{Duplicated or Conflicting
Features}\label{duplicated-or-conflicting-features-1}

\subsubsection{DUP-01: Dual In-Buffer Completion
Frameworks}\label{dup-01-dual-in-buffer-completion-frameworks}

\begin{itemize}
\tightlist
\item
  Location: org heading "Completion "at-point""
\item
  Status: duplicate and conflicting
\item
  Evidence: both \texttt{corfu} (with \texttt{global-corfu-mode}) and
  \texttt{company} (with \texttt{company-posframe}) are loaded, causing
  overlapping UI popups and conflicting TAB/RET keybindings in
  programming modes.
\item
  Recommendation: purge all \texttt{company} packages. Retain
  \texttt{corfu} as the sole in-buffer completion frontend, augmented by
  \texttt{cape} for supplementary completion-at-point backends (dabbrev,
  file, dictionary).
\item
  Risk: Medium; Effort: Low; Confidence: High
\end{itemize}

\subsubsection{\texorpdfstring{DUP-02: Python LSP Client Coexistence
(\texttt{lsp-mode} vs
\texttt{eglot})}{DUP-02: Python LSP Client Coexistence (lsp-mode vs eglot)}}\label{dup-02-python-lsp-client-coexistence-lsp-mode-vs-eglot}

\begin{itemize}
\tightlist
\item
  Location: org heading "Lang: Python/lsp"
\item
  Status: conflicting if unmanaged
\item
  Evidence: \texttt{lsp-mode} (\texttt{lsp-pyright}) is configured as
  the default for \texttt{.py} files, while \texttt{eglot} is intended
  for percent-format Jupyter notebooks (\texttt{\#\ \%\%}) in
  \texttt{notebooks/} subdirectories. Without strict buffer-local
  isolation, both clients attempt to manage the same buffers, causing
  CPU contention, duplicate diagnostics, and conflicting edits.
\item
  Recommendation: enforce strict mutual exclusivity. Ordinary Python
  files use \texttt{lsp-mode} with \texttt{basedpyright} and
  \texttt{ruff-format-on-save-mode}. Files inside \texttt{notebooks/}
  subdirectories automatically disconnect \texttt{lsp-mode} and invoke
  \texttt{eglot} with the multi-server setup
  (\texttt{basedpyright-langserver} + \texttt{ruff\ server}).
\item
  Risk: Medium; Effort: Medium; Confidence: High
\end{itemize}

\subsubsection{DUP-03: Syntax Error in Notebook
Hook}\label{dup-03-syntax-error-in-notebook-hook}

\begin{itemize}
\tightlist
\item
  Location: org heading "Lang: Python/lsp", line
  \texttt{(add-hook\ \textquotesingle{}python-ts-mode-hook\ ...)}
\item
  Status: conflicting / broken code
\item
  Evidence: the provided code for auto-activating Eglot on notebook
  files contains an unclosed \texttt{and} expression:
\end{itemize}

\begin{Shaded}
\begin{Highlighting}[]
\NormalTok{(when (and buffer{-}file{-}name }
\NormalTok{           (string{-}match{-}p "notebooks" (buffer{-}file{-}name))}
\NormalTok{  (remove{-}hook ...))}
\end{Highlighting}
\end{Shaded}

This triggers \texttt{Wrong\ type\ argument:\ integer-or-marker-p,\ nil}
or Lisp syntax errors on buffer load.

\begin{itemize}
\tightlist
\item
  Recommendation: correct the parentheses matching for the \texttt{and}
  form.
\item
  Risk: High; Effort: Low; Confidence: High
\end{itemize}

