\subsection{\texorpdfstring{\textbf{ENH-01: Implement deterministic
Python LSP
dispatch}}{ENH-01: Implement deterministic Python LSP dispatch}}\label{enh-01-implement-deterministic-python-lsp-dispatch}

\begin{itemize}
\tightlist
\item
