\subsubsection{\texorpdfstring{OBS-05: \texttt{global-flycheck-mode}
conflicts with Eglot’s
Flymake}{OBS-05: global-flycheck-mode conflicts with Eglot’s Flymake}}\label{obs-05-global-flycheck-mode-conflicts-with-eglots-flymake}

\begin{itemize}
\tightlist
\item
  \textbf{Location:} \texttt{site-pkgs.org}, heading
  \texttt{Lang:\ LSP\ →\ Lang:\ LSP.mode},
  \texttt{use-package\ flycheck} with
  \texttt{(global-flycheck-mode\ 1)}; \texttt{use-package\ eglot} also
  active.
\item
  \textbf{Status:} duplicate / conflicting
\item
  \textbf{Evidence:} \texttt{(global-flycheck-mode\ 1)} enables Flycheck
  globally. Eglot uses Flymake internally for diagnostics. In
  Eglot‑managed buffers, the two systems can both try to report errors,
  or Flycheck may override Flymake, producing inconsistent diagnostics.
\item
  \textbf{Recommendation:} Either (a) use \texttt{flycheck-eglot} to let
  Flycheck consume Eglot diagnostics, or (b) disable \texttt{flycheck}
  in Eglot‑managed buffers via a hook. If \texttt{lsp-mode} uses
  \texttt{:flycheck} (as configured), keep Flycheck only for
  \texttt{lsp-mode} and use Flymake for Eglot. A deterministic
  per‑buffer hook is provided in ENH‑01.
\item
  \textbf{Risk:} High (diagnostics may be duplicated or missing);
  \textbf{Effort:} Medium; \textbf{Confidence:} High.
\end{itemize}

