\begin{Shaded}
\begin{Highlighting}[]
\NormalTok{;; Replace the final add{-}hook in "Lang: Python/lsp"}
\NormalTok{(defun h7/python{-}notebook{-}p ()}
\NormalTok{  "Return non{-}nil when the current buffer is a Jupytext notebook.}
