\NormalTok{       (or (string{-}match{-}p "/notebooks/" buffer{-}file{-}name)}
\NormalTok{           (save{-}excursion}
\NormalTok{             (goto{-}char (point{-}min))}
\NormalTok{             (re{-}search{-}forward "\^{}\# \%\%" (min (point{-}max) 2000) t)))))}

\NormalTok{(defun h7/python{-}apply{-}lsp{-}backend ()}
