\NormalTok{idempotent and safe to call from a mode hook."}
\NormalTok{  (when (derived{-}mode{-}p \textquotesingle{}python{-}mode \textquotesingle{}python{-}ts{-}mode)}
\NormalTok{    (if (h7/python{-}notebook{-}p)}
