\NormalTok{      (h7/python{-}use{-}lsp))))}

\NormalTok{(add{-}hook \textquotesingle{}python{-}mode{-}hook \#\textquotesingle{}h7/python{-}apply{-}lsp{-}backend)}
\NormalTok{(add{-}hook \textquotesingle{}python{-}ts{-}mode{-}hook \#\textquotesingle{}h7/python{-}apply{-}lsp{-}backend)}
