\subsection{Deterministic client
selection}\label{deterministic-client-selection}

\subsubsection{Change DUP-08: replace hook-order-dependent backend
selection}\label{change-dup-08-replace-hook-order-dependent-backend-selection}

\begin{itemize}
\tightlist
\item
  Target heading: \texttt{Lang\ LSP.mode} / \texttt{lang-lsp.mode}
\item
  Action: replace the \texttt{python-mode} and \texttt{python-ts-mode}
  LSP hooks with one deterministic selector
\item
  Rollback: restore the original
  \texttt{unless\ bound-and-true-p\ h7python-use-eglot} hooks
\end{itemize}

\begin{Shaded}
\begin{Highlighting}[]
\NormalTok{;;; \#PNX(DUP{-}08): Added deterministic selection of exactly one Python LSP client per buffer}
\NormalTok{(defun h7python{-}notebook{-}buffer{-}p ()}
\NormalTok{  "Return non{-}nil for Python buffers beneath a project{-}local \textasciigrave{}notebooks/\textquotesingle{} directory."}
\NormalTok{  (and buffer{-}file{-}name}
\NormalTok{       (when{-}let* ((project (project{-}current))}
\NormalTok{                   (root (project{-}root project)))}
\NormalTok{         (string{-}prefix{-}p}
\NormalTok{          (expand{-}file{-}name "notebooks/" root)}
\NormalTok{          (expand{-}file{-}name buffer{-}file{-}name)))))}

\NormalTok{(defun h7python{-}lsp{-}backend ()}
\NormalTok{  "Return \textasciigrave{}eglot\textquotesingle{} or \textasciigrave{}lsp\textquotesingle{} for the current Python buffer."}
\NormalTok{  (cond}
\NormalTok{   ((and (boundp \textquotesingle{}h7python{-}use{-}eglot) h7python{-}use{-}eglot) \textquotesingle{}eglot)}
\NormalTok{   ((h7python{-}notebook{-}buffer{-}p) \textquotesingle{}eglot)}
\NormalTok{   (t \textquotesingle{}lsp)))}

\NormalTok{(defun h7python{-}lsp{-}maybe{-}start ()}
\NormalTok{  "Start exactly one Python LSP client for the current buffer."}
\NormalTok{  (when (derived{-}mode{-}p \textquotesingle{}python{-}base{-}mode)}
\NormalTok{    (pcase (h7python{-}lsp{-}backend)}
\NormalTok{      (\textquotesingle{}eglot}
\NormalTok{       (setq{-}local h7python{-}use{-}eglot t)}
\NormalTok{       (when (fboundp \textquotesingle{}ruff{-}format{-}on{-}save{-}mode)}
\NormalTok{         (ruff{-}format{-}on{-}save{-}mode {-}1))}
\NormalTok{       (eglot{-}ensure))}
\NormalTok{      (\textquotesingle{}lsp}
\NormalTok{       (setq{-}local h7python{-}use{-}eglot nil)}
\NormalTok{       (when (fboundp \textquotesingle{}ruff{-}format{-}on{-}save{-}mode)}
\NormalTok{         (ruff{-}format{-}on{-}save{-}mode 1))}
\NormalTok{       (lsp{-}deferred)))))}
\end{Highlighting}
\end{Shaded}

