\NormalTok{;;; \#PNX(DUP{-}08): Replaced separate lsp{-}mode Python hooks with the deterministic selector}
\NormalTok{:hook ((python{-}mode python{-}ts{-}mode) . h7python{-}lsp{-}maybe{-}start)}
